import { expect, test, type Page } from "@playwright/test";

import type { HomeSnapshot } from "../lib/home-api";
import { parseEffectiveThemeResponse } from "../lib/theme-config";
import { E2E_PERSONAL_APPEARANCE, mockAuthedApp } from "./_app-mocks";
// Generated by PersonalThemeCompiler over legacy_m1_compiled_scheme("bowhead")
// with custom #2563EB and preset plum; both have zero blocking validation issues.
import themes from "./fixtures/home-accent-themes.json";

type Mode = "light" | "dark";
type Theme = keyof typeof themes;
const outputIcon = ".home-work-row-output .home-work-row-icon";
// Unread work is marked by a bold title (no accent dot) and the "未读" screen-reader note.
const unreadTitle = ".unified-work-item.is-unread .unified-work-title";
const timestamp = "2026-09-09T06:00:00Z";

function snapshot(): HomeSnapshot {
  return {
    version: "home.snapshot.v1",
    generatedAt: timestamp,
    scope: { workspaceId: "ws_smoke", workspaceName: "Smoke workspace" },
    attentionScope: "user",
    attention: [{
      id: "notice_accent", source: "notification", nativeType: "approval.required",
      priority: "high", title: "待确认的事项", body: "确认后继续",
      actionUrl: "/", subjectType: null, subjectId: null, createdAt: timestamp,
    }],
    active: [],
    outputs: [{
      id: "report_accent", kind: "report", title: "外观回归报告", format: "pdf",
      actionUrl: "/reports/", sessionId: null, createdAt: timestamp,
      updatedAt: timestamp, metadata: {},
    }],
    counts: { attention: 1, active: 0, outputs: 1 },
    partial: false,
    issues: [],
  };
}

async function installFixture(page: Page, mode: Mode, initialTheme: Theme, home = snapshot(), error = false) {
  let theme = initialTheme;
  let rowVersion = 1;
  const personal = () => ({
    ...E2E_PERSONAL_APPEARANCE,
    materialized: true,
    rowVersion,
    overrides: { mode, accent: themes[theme].accent },
    effective: { ...E2E_PERSONAL_APPEARANCE.effective, mode, colorScheme: themes[theme].colorScheme },
    sources: { ...E2E_PERSONAL_APPEARANCE.sources, mode: "user", accent: "user" },
    registries: {
      ...E2E_PERSONAL_APPEARANCE.registries,
      accent: { version: 1, items: [{
        id: "plum", labelKey: "appearance.accent.plum", value: themes.plum.accent,
        swatch: Object.fromEntries((["light", "dark"] as const).map((m) => [m, {
          primary: themes.plum.colorScheme[m].accent,
          onPrimary: themes.plum.colorScheme[m].accentInk,
        }])),
        availability: "available",
      }] },
    },
  });
  await mockAuthedApp(page);
  await page.route("**/api/v1/theme/effective", (route) => route.fulfill({ json: parseEffectiveThemeResponse({
    schemaVersion: 2,
    brand: {
      applicationName: "Bowhead", logoAlt: "Bowhead",
      logoOnLight: { kind: "text", text: "Bowhead" },
      logoOnDark: { kind: "text", text: "Bowhead" },
      mark: { kind: "generatedInitial", text: "B" },
      favicon: { kind: "generatedInitial", text: "B" },
    },
    effective: {
      ...personal().effective, version: 1,
      colorProfile: { type: "preset", id: "bowhead" }, chartPalette: "default",
    },
    locks: {},
    source: {
      mode: "user", colorProfile: "user", colorScheme: "user",
      typographyProfile: "product", typeScale: "product", density: "product",
      radius: "product", motion: "product", chartPalette: "product",
    },
    userConfig: { version: 1, mode },
    team: { id: "team_smoke", configurationType: "legacy", themeRevision: null, revisionId: null },
  }) }));
  await page.route("**/api/v1/theme/personal", async (route) => {
    if (route.request().method() === "PATCH") {
      expect(route.request().postDataJSON()).toEqual({ changes: { accent: themes.plum.accent } });
      theme = "plum";
      rowVersion += 1;
    }
    await route.fulfill({ json: personal(), headers: { ETag: `"personal-v3:${String(rowVersion).padStart(64, "0")}"` } });
  });
  await page.route("**/api/v1/home/snapshot**", (route) => route.fulfill({
    status: error ? 500 : 200, json: error ? { detail: "unavailable" } : home,
  }));
  await page.route(/\/api\/v1\/sessions(?:\?.*)?$/, (route) => route.fulfill({ json: { groups: [{
    id: "today", label: "今天", items: [
      { id: "s_accent_unread", title: "待阅读的工作", state: "done", unread: true },
      { id: "s_accent_read", title: "已经阅读的工作", state: "done", unread: false },
    ],
  }] } }));
}

/** The computed colour of a CSS colour expression, resolved the way the page resolves it. */
async function resolvedColor(page: Page, value: string): Promise<string> {
  return page.evaluate((color) => {
    const probe = document.createElement("span");
    probe.style.color = color;
    document.body.append(probe);
    const resolved = getComputedStyle(probe).color;
    probe.remove();
    return resolved;
  }, value);
}

function rgb(hex: string) {
  return `rgb(${[1, 3, 5].map((offset) => parseInt(hex.slice(offset, offset + 2), 16)).join(", ")})`;
}

async function expandSidebar(page: Page) {
  const mobile = page.getByTestId("mobile-topbar-hamburger");
  if (await mobile.isVisible()) await mobile.click();
  else {
    const expand = page.getByRole("button", { name: "展开侧栏", exact: true });
    if (await expand.isVisible()) await expand.click();
  }
  await expect(page.locator(unreadTitle)).toBeVisible();
}

async function expectTheme(page: Page, mode: Mode, theme: Theme) {
  const colors = themes[theme].colorScheme[mode];
  await expect(page.locator("html")).toHaveAttribute("data-theme", mode);
  await expect.poll(() => page.evaluate(() => {
    const style = getComputedStyle(document.documentElement);
    return ["--c-accent", "--c-pos", "--c-bg"].map((key) => style.getPropertyValue(key).trim());
  })).toEqual([colors.accent, colors.positive, colors.background]);
  return colors;
}

async function expectUnreadTitle(page: Page) {
  const weight = await page.locator(unreadTitle).evaluate((element) => Number(getComputedStyle(element).fontWeight));
  expect(weight).toBeGreaterThanOrEqual(600);
}

async function expectAccentSurfaces(page: Page, mode: Mode, theme: Theme) {
  // The home header and work rows use neutral roles (P2 page spec: no coloured eyebrow dot or icon blocks);
  // the theme switch is checked on the tokens themselves and on the neutral roles they feed.
  const colors = await expectTheme(page, mode, theme);
  await expect(page.locator(".home-work-kicker")).toHaveCSS("color", await resolvedColor(page, "var(--c-ink-4)"));
  await expect.poll(() => page.locator(".home-work-kicker").evaluate((element) =>
    getComputedStyle(element, "::before").content,
  )).toBe("none");
  await expectUnreadTitle(page);
  await expect(page.locator(outputIcon)).toHaveCSS("color", await resolvedColor(page, "var(--c-ink-2)"));
  await expect(page.locator(outputIcon)).toHaveCSS("background-color", "rgba(0, 0, 0, 0)");
  return colors;
}

for (const mode of ["light", "dark"] as const) {
  for (const theme of ["blue", "plum"] as const) {
    test(`home accent and neutral roles: ${theme} ${mode}`, async ({ page }, testInfo) => {
      await page.setViewportSize({ width: 1600, height: 1000 });
      await installFixture(page, mode, theme);
      await page.goto("/");
      await expandSidebar(page);
      await expectAccentSurfaces(page, mode, theme);
      const colors = themes[theme].colorScheme[mode];
      await expect(page.locator(".home-work-updated > span")).toHaveCSS("background-color", rgb(colors.ink3));
      const note = page.locator(".home-work-proposal-note");
      await expect(note).toHaveText("执行前会确认必要材料、权限和可用工具。");
      await expect(note.locator(":scope > svg")).toHaveCSS("color", rgb(colors.ink3));
      await expect(note.locator(":scope > svg")).toHaveAttribute("aria-hidden", "true");
      await expect(note.locator(":scope > svg")).toHaveAttribute("focusable", "false");
      const read = page.locator(".unified-work-item", { hasText: "已经阅读的工作" });
      expect(await read.locator(".unified-work-title").evaluate((element) => Number(getComputedStyle(element).fontWeight))).toBeLessThan(600);
      await expect(page.locator(".unified-work-item.is-unread")).toHaveCount(1);
      await expect(page.locator(".unified-work-item.is-unread")).toContainText("未读");
      await page.screenshot({ path: testInfo.outputPath(`home-${theme}-${mode}.png`), animations: "disabled" });
    });
  }
}

test("saved accent updates the current home without reload and survives reload", async ({ page }) => {
  await page.setViewportSize({ width: 1600, height: 1000 });
  await installFixture(page, "light", "blue");
  await page.goto("/");
  await expandSidebar(page);
  await expectAccentSurfaces(page, "light", "blue");
  await page.getByRole("button", { name: "账户", exact: true }).click();
  await page.getByRole("menuitem", { name: "个人设置", exact: true }).click();
  const dialog = page.getByRole("dialog", { name: "个人设置", exact: true });
  await dialog.getByRole("button", { name: "外观", exact: true }).click();
  const saved = page.waitForResponse((response) => response.url().endsWith("/api/v1/theme/personal") && response.request().method() === "PATCH" && response.status() === 200);
  await dialog.getByTestId("personal-appearance-accent").getByRole("button", { name: /李紫/ }).click();
  await saved;
  await dialog.getByRole("button", { name: "完成", exact: true }).click();
  await expectAccentSurfaces(page, "light", "plum");
  await page.reload();
  await expandSidebar(page);
  await expectAccentSurfaces(page, "light", "plum");
});

test("unread work stays marked on reports and in the mobile drawer", async ({ page }, testInfo) => {
  await page.setViewportSize({ width: 1600, height: 1000 });
  await installFixture(page, "light", "blue");
  await page.route("**/api/v1/reports**", (route) => route.fulfill({ json: { items: [] } }));
  await page.goto("/");
  await expandSidebar(page);
  await page.getByRole("link", { name: "我的报告", exact: true }).click();
  await expect(page).toHaveURL(/\/reports\/?$/);
  await expectUnreadTitle(page);
  await page.setViewportSize({ width: 390, height: 844 });
  await page.goto("/");
  await expect(page.locator(".home-work-proposal-note")).toBeVisible();
  await expect.poll(() => page.evaluate(() => document.documentElement.scrollWidth <= innerWidth)).toBe(true);
  await expandSidebar(page);
  await expect(page.locator(".unified-work-item.is-unread")).toContainText("未读");
  await expectUnreadTitle(page);
  await page.screenshot({ path: testInfo.outputPath("mobile-sidebar-blue.png"), animations: "disabled" });
});

for (const state of ["clear", "paused", "error"] as const) {
  test(`business ${state} state retains its semantic color`, async ({ page }) => {
    const home = snapshot();
    if (state === "clear") {
      home.attention = [];
      home.outputs = [];
      home.counts = { attention: 0, active: 0, outputs: 0 };
    } else if (state === "paused") {
      home.active = [{
        id: "matrix_accent", engine: "matrix", nativeStatus: "paused", title: "暂停的工作",
        subtitle: null, progress: null, actionUrl: "/", sessionId: null,
        startedAt: timestamp, updatedAt: timestamp, metadata: {},
      }];
      home.counts.active = 1;
    }
    await installFixture(page, "light", "blue", home, state === "error");
    await page.goto("/");
    const colors = await expectTheme(page, "light", "blue");
    const [selector, color] = {
      clear: [".home-work-clear > svg", rgb(colors.positive)],
      // Paused text uses the warning ink token (the darker text variant of the warning colour).
      paused: [".home-work-live-paused", await resolvedColor(page, "var(--c-warn-ink)")],
      error: [".home-work-state-icon-error", rgb(colors.error)],
    }[state];
    await expect(page.locator(selector)).toHaveCSS("color", color);
  });
}
